      "category": "sequence_interest",
      "rationale": "Anchor positions to recency across all four category models: the rightmost nonpadding token receives position 1 and padding remains 0. The generated predictor imports this same model class, keeping masked training and appended-mask inference consistent without changing checkpoint shapes.",
      "edits": [
        {
          "find": "        pos = nonpadding.cumsum(dim=1) * nonpadding",
          "replace": "        pos = nonpadding.flip(dims=[1]).cumsum(dim=1).flip(dims=[1]) * nonpadding"
        }
      ]
    }
  ],
  "change_summary": "Replace chronological position IDs with reverse nonpadding ranks. Preserve masked-target training, appended-mask readout, model topology, scoring, loss, optimizer, and category routing."
}
